#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long fastExponentiation(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<long long> precomputedFactorials;

long long computeNCr(int n, int r) {
    if (n < r) return 0;
    long long numerator = precomputedFactorials[n];
    long long denominator = (precomputedFactorials[n - r] * precomputedFactorials[r]) % MOD;
    return (numerator * fastExponentiation(denominator, MOD - 2)) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int maxN = 200001;
    precomputedFactorials.resize(maxN);
    precomputedFactorials[0] = 1;
    for (int i = 1; i < maxN; i++) {
        precomputedFactorials[i] = (precomputedFactorials[i - 1] * i) % MOD;
    }
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << precomputedFactorials[n] << "\n";
        return 0;
    }
    if (k == n - 1) {
        cout << 2LL * n << "\n";
        return 0;
    }
    int filledColumns = n - (int)k;
    long long waysToChooseFilledCols = computeNCr(n, filledColumns);
    long long totalWays = 0;
    for (int emptyCols = 0; emptyCols <= filledColumns; emptyCols++) {
        long long choose = computeNCr(filledColumns, emptyCols);
        long long fillWays = fastExponentiation(filledColumns - emptyCols, n);
        long long val = (choose * fillWays) % MOD;
        if (emptyCols % 2 == 1) val = (MOD - val) % MOD;
        totalWays = (totalWays + val) % MOD;
    }
    totalWays = (totalWays * waysToChooseFilledCols) % MOD;
    totalWays = (totalWays * 2) % MOD;
    cout << totalWays << "\n";
    return 0;
}
